/**
 * Environment of the e2e run. Defaults follow the ADR-0002 topology; nothing here is a secret.
 *
 *   E2E_BASE_URL            origin of the nginx front end (same origin for the app and /api)
 *   E2E_STRAPI_URL          Strapi's own port: admin panel, direct anonymous reads, test setup
 *   STRAPI_ADMIN_EMAIL      development super admin created by the Strapi bootstrap (ADR-0002)
 *   STRAPI_ADMIN_PASSWORD   its password. Used only by the Node test process (US-01-AC-03)
 *
 * The admin credentials have no default on purpose. Put them in the git-ignored env file of the
 * repository root, or export them; they are never printed and never reach a browser context.
 */
try {
  // Node >= 20.12. A missing file is fine: values already in the environment win.
  process.loadEnvFile('../.env');
} catch {
  /* no env file: rely on the process environment */
}

export const BASE_URL = process.env['E2E_BASE_URL'] ?? 'http://localhost:8080';
export const STRAPI_URL = process.env['E2E_STRAPI_URL'] ?? 'http://localhost:1337';

export function adminCredentials(): { email: string; password: string } {
  const email = process.env['STRAPI_ADMIN_EMAIL'];
  const password = process.env['STRAPI_ADMIN_PASSWORD'];
  if (!email || !password) {
    // A hard failure, not a skip: US-01-AC-03 cannot be verified without the write flow of ADR-0002.
    throw new Error('STRAPI_ADMIN_EMAIL and STRAPI_ADMIN_PASSWORD must be set for the US-01-AC-03 test (see e2e/support/env.ts).');
  }
  return { email, password };
}
import { expect, type Locator, type Page } from '@playwright/test';

/**
 * Helpers for the step 1 form. Everything is found the way a person or assistive technology finds
 * it: by label, by role, by visible text. Values are fictitious (specs/US-01/seed-fields.md).
 */

export const CO_LABELS = [
  'Tipo de documento',
  'Número de documento',
  'Nombre completo',
  'Fecha de nacimiento',
  'Ciudad',
  'Placa',
  'Marca',
  'Línea',
  'Modelo (año)',
  'Autorizo el tratamiento de mis datos personales.',
];

export const CL_LABELS = [
  'RUT',
  'Nombre completo',
  'Fecha de nacimiento',
  'Ciudad',
  'Patente',
  'Marca',
  'Modelo',
  'Año',
  'Acepto el tratamiento de mis datos personales.',
];

/** US-01-AC-04 values for Colombia. Selects use the visible option text. */
export const CO_VALID: Record<string, string | boolean> = {
  'Tipo de documento': 'Cédula de ciudadanía',
  'Número de documento': '1012345678',
  'Nombre completo': 'Ana Prueba Ficticia',
  'Fecha de nacimiento': '1990-05-15',
  Ciudad: 'Medellín',
  Placa: 'ABC123',
  Marca: 'Mazda',
  Línea: '3 Touring',
  'Modelo (año)': '2022',
  'Autorizo el tratamiento de mis datos personales.': true,
};

export const CO_CONSENT = 'Autorizo el tratamiento de mis datos personales.';

function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** A label, allowing the optional required marker ("Placa *") a form may add after it. */
export function labelPattern(label: string): RegExp {
  return new RegExp(`^\\s*${escapeRegExp(label)}\\s*(\\*|\\(obligatorio\\))?\\s*$`);
}

export function field(page: Page, label: string): Locator {
  return page.getByLabel(labelPattern(label));
}

export function continuar(page: Page): Locator {
  return page.getByRole('button', { name: 'Continuar' });
}

/**
 * The visible labels of the form, in document order. `<label>` has no ARIA role that lists them,
 * so this is the one CSS locator; the order of labels is what AC-01 asserts.
 */
export async function visibleLabels(page: Page): Promise<string[]> {
  const texts = await page.locator('label').allInnerTexts();
  return texts.map((t) => t.replace(/\*/g, '').replace(/\s+/g, ' ').trim()).filter((t) => t.length > 0);
}

/** Fill one control by label with the gesture that suits its kind. */
export async function fillField(page: Page, label: string, value: string | boolean): Promise<void> {
  const control = field(page, label);
  const tag = await control.evaluate((el) => el.tagName.toLowerCase());
  const type = await control.evaluate((el) => (el as HTMLInputElement).type);
  if (tag === 'select') {
    await control.selectOption({ label: value as string });
  } else if (type === 'checkbox') {
    if (value) await control.check();
    else await control.uncheck();
  } else {
    await control.fill(value as string);
  }
}

/** Fill the whole Colombia form; `overrides` replace values, `null` leaves a field untouched. */
export async function fillColombia(page: Page, overrides: Record<string, string | boolean | null> = {}): Promise<void> {
  const values: Record<string, string | boolean | null> = { ...CO_VALID, ...overrides };
  for (const [label, value] of Object.entries(values)) {
    if (value === null) continue;
    await fillField(page, label, value);
  }
}

export async function expectDescribedBy(page: Page, label: string, message: string): Promise<void> {
  await expect(field(page, label)).toHaveAccessibleDescription(new RegExp(escapeRegExp(message)));
}

/** Escape text for use inside a RegExp built by a test. */
export const escape = escapeRegExp;
import { expect, type APIRequestContext, type Locator, type Page } from '@playwright/test';
import { continuar, field, fillColombia, fillField } from './form';
import type { AdminSession, ScopedToken } from './strapi-admin';

/**
 * Helpers for step 2 (the plan list) and for the US-02 write flow of the e2e tests. Everything on
 * the page is found by role, name or visible text: plans are native radios (US-02-Q-13), so a plan
 * is `getByRole('radio', { name: <plan name> })`. Values are fictitious (specs/US-02/seed-plans.md).
 */

export const HEADING = 'Elige tu plan';
export const TITLE = 'Elige tu plan | Cotizador de seguro de auto';

/** The browser clock of every US-02 e2e test, so that the prices are stable (spec section 11). */
export const TODAY = new Date('2026-11-21T10:00:00');

export const CO_PLAN_NAMES = ['Plan Básico', 'Plan Clásico', 'Plan Total'];
export const CL_PLAN_NAMES = ['Plan Esencial', 'Plan Protegido', 'Plan Premium'];
/** Final prices of the seed with the step 1 values below at 2026-11-21 (US-02-AC-07). */
export const CO_PRICES = ['$935.000', '$1.540.000', '$2.310.000'];
export const CL_PRICES = ['$319.000', '$528.000', '$792.000'];
/** Seeded plans that are never offered: draft only or inactive (US-02-AC-01, AC-08). */
export const CO_HIDDEN_NAMES = ['Plan Joven', 'Plan Total Plus'];
export const CL_HIDDEN_NAMES = ['Plan Flex', 'Plan Premium Plus'];

export const CL_CONSENT = 'Acepto el tratamiento de mis datos personales.';

/** "I completed step 1 in Chile" of US-02 spec section 5. */
export const CL_VALID: Record<string, string | boolean> = {
  RUT: '12.345.678-5',
  'Nombre completo': 'Ana Prueba Ficticia',
  'Fecha de nacimiento': '1990-05-15',
  Ciudad: 'Santiago',
  Patente: 'BCDF12',
  Marca: 'Kia',
  Modelo: 'Rio 5',
  Año: '2022',
  [CL_CONSENT]: true,
};

export async function fillChile(page: Page, overrides: Record<string, string | boolean | null> = {}): Promise<void> {
  const values: Record<string, string | boolean | null> = { ...CL_VALID, ...overrides };
  for (const [label, value] of Object.entries(values)) {
    if (value === null) continue;
    await fillField(page, label, value);
  }
}

/** A price as the page may write it: whitespace between the symbol and the digits is allowed (BR-03). */
export function pricePattern(price: string): RegExp {
  const digits = price.replace(/[^\d.]/g, '').replace(/\./g, '\\.');
  return new RegExp(`\\$\\s*${digits}(?![\\d.])`);
}

export function plan(page: Page, name: string): Locator {
  return page.getByRole('radio', { name, exact: true });
}

export function plans(page: Page): Locator {
  return page.getByRole('radio');
}

export function atras(page: Page): Locator {
  return page.getByRole('button', { name: 'Atrás' });
}

/** The plan names shown, in order (each option's accessible name is its plan name, US-02-AC-17). */
export async function expectPlanNames(page: Page, names: string[]): Promise<void> {
  await expect(plans(page)).toHaveCount(names.length);
  for (const [index, name] of names.entries()) {
    await expect(plans(page).nth(index)).toHaveAccessibleName(name);
  }
}

/** The final price of each plan is part of its accessible description (US-02-AC-17). */
export async function expectPrices(page: Page, names: string[], prices: string[]): Promise<void> {
  for (const [index, name] of names.entries()) {
    await expect(plan(page, name)).toHaveAccessibleDescription(pricePattern(prices[index]));
  }
}

/** Every control of step 1 shows the value that was entered (US-01-AC-04, AC-20, AC-21); no error is shown. */
export async function expectEntered(page: Page, values: Record<string, string | boolean>): Promise<void> {
  for (const [label, value] of Object.entries(values)) {
    const control = field(page, label);
    const tag = await control.evaluate((el) => el.tagName.toLowerCase());
    const type = await control.evaluate((el) => (el as HTMLInputElement).type);
    if (tag === 'select') {
