export function wizardEntryWithPlan(country: string, values: Record<string, unknown>, planKey: string | null): string {
  return JSON.stringify({
    version: 1,
    country,
    step1: { values },
    ...(planKey === null ? {} : { plan: { key: planKey } }),
  });
}

