      const link = (label: string): WireNode => ({ type: 'link', url: 'https://example.invalid', children: [text(label)] });
      parse([paragraph(link('uno'), text(' '), link('dos'), text(' '), link('tres'))]);
      expect(warn).toHaveBeenCalledTimes(3);
