    it('ADR-0009 bold, italic, underline and strikethrough render as strong, em, u and s', () => {
      const el = render([paragraph(text('a', { bold: true }), text('b', { italic: true }), text('c', { underline: true }), text('d', { strikethrough: true }))]);
      expect(el.querySelector('strong')?.textContent).toBe('a');
      expect(el.querySelector('em')?.textContent).toBe('b');
      expect(el.querySelector('u')?.textContent).toBe('c');
      expect(el.querySelector('s')?.textContent).toBe('d');
    });

    it('ADR-0009 several marks on one text nest: the text is inside both strong and em', () => {
      const el = render([paragraph(text('mixto', { bold: true, italic: true }))]);
      const strong = el.querySelector('strong');
      const em = el.querySelector('em');
      expect(strong && em).toBeTruthy();
      const inner = Array.from(el.querySelectorAll('strong, em')).find((e) => e.textContent === 'mixto' && e.children.length === 0 && e.childNodes.length === 1);
      expect(inner).toBeTruthy();
      expect(inner?.closest('strong')).not.toBeNull();
      expect(inner?.closest('em')).not.toBeNull();
    });

    it('ADR-0009 an inline code mark is plain text: no code element', () => {
      const el = render([paragraph(text('x', { code: true }))]);
      expect(el.querySelectorAll('code')).toHaveLength(0);
      expect(el.textContent).toContain('x');
