const warn = (w: string) => console.warn(`rich text: ${w}`);
function spans(children: unknown, nodeType: string): RichTextSpan[] | null {
  if (!Array.isArray(children)) return null;
  const out: RichTextSpan[] = [];
  for (const c of children) {
    if (isRec(c) && c['type'] === 'text' && typeof c['text'] === 'string') out.push({ text: c['text'], bold: c['bold'] === true, italic: c['italic'] === true, underline: c['underline'] === true, strikethrough: c['strikethrough'] === true });
    else if (isRec(c) && c['type'] === 'link') { warn('link'); const inner = spans(c['children'], 'link'); if (inner) out.push(...inner); }
    else warn(name(isRec(c) ? c['type'] : undefined));
  }
  return out;
}
const blank = (s: RichTextSpan[]) => s.every((x) => x.text.trim() === '');
function parseList(node: Record<string, unknown>, depth: number): RichTextList | null {
  if (node['format'] !== 'ordered' && node['format'] !== 'unordered') { warn('list'); return null; }
  if (!Array.isArray(node['children'])) { warn('list'); return null; }
  const items: RichTextListItem[] = [];
  for (const child of node['children']) {
    if (isRec(child) && child['type'] === 'list-item') { const s = spans(child['children'], 'list-item'); if (s && !blank(s)) items.push({ spans: s, lists: [] }); }
    else if (isRec(child) && child['type'] === 'list') {
      if (depth >= 6) { warn('list-depth'); continue; }
      const nested = parseList(child, depth + 1);
      if (nested) { if (items.length === 0) items.push({ spans: [], lists: [] }); items[items.length - 1].lists.push(nested); }
    } else warn(name(isRec(child) ? child['type'] : undefined));
  }
  return { ordered: node['format'] === 'ordered', items };
}
export function parseRichTextBlocks(value: unknown): RichTextBlock[] | null {
  if (!Array.isArray(value)) { warn('body'); return null; }
  const raw: ({ kind: 'paragraph'; spans: RichTextSpan[] } | { kind: 'heading'; level: number; spans: RichTextSpan[] } | { kind: 'list'; list: RichTextList })[] = [];
  for (const node of value) {
    if (!isRec(node)) { warn('unknown'); continue; }
