  const out: RichTextBlock[] = raw.map((r) => (r.kind === 'heading' ? { kind: 'heading', depth: r.level - min, spans: r.spans } : r));
  const hasText = (blocks: RichTextBlock[]) => blocks.some((b) => b.kind === 'list' ? true : !blank(b.spans));
