import { Injectable, InjectionToken, inject } from '@angular/core';
import { PaymentGateway, type PaymentRequest, type PaymentResult } from './payment-gateway';
export const SIMULATED_PROCESSING_MS = 1500;
export const PAYMENT_DELAY = new InjectionToken<(ms: number, signal: AbortSignal) => Promise<void>>('PAYMENT_DELAY', { providedIn: 'root', factory: () => (ms, signal) => new Promise<void>((resolve, reject) => {
  if (signal.aborted) { reject(new DOMException('aborted', 'AbortError')); return; }
  const id = setTimeout(() => resolve(), ms);
  signal.addEventListener('abort', () => { clearTimeout(id); reject(new DOMException('aborted', 'AbortError')); }, { once: true });
}) });
export class PaymentInProgressError extends Error {}
@Injectable()
export class SimulatedPaymentGateway extends PaymentGateway {
  private readonly delay = inject(PAYMENT_DELAY);
  private inFlight = false;
  async pay(request: PaymentRequest, signal: AbortSignal): Promise<PaymentResult> {
    if (this.inFlight) throw new PaymentInProgressError();
    this.inFlight = true;
    try { await this.delay(SIMULATED_PROCESSING_MS, signal); return { status: request.simulatedOutcome }; } finally { this.inFlight = false; }
  }
}
