export function maskDocumentNumber(value: string): { text: string; accessibleText: string } {
  const isChar = (c: string) => /[\p{L}\p{N}]/u.test(c);
  const n = Array.from(value).filter(isChar).length;
  const k = Math.min(4, Math.floor(n / 2));
  let seen = 0; let text = ''; let tailStart = -1;
  const chars = Array.from(value);
  chars.forEach((c, i) => {
    if (!isChar(c)) { text += c; return; }
    seen++;
    if (seen > n - k) { if (tailStart < 0) tailStart = i; text += c; } else text += '•';
  });
  const tail = tailStart < 0 ? '' : chars.slice(tailStart).join('');
  return { text, accessibleText: tail ? `Número oculto, termina en ${tail}` : 'Número oculto' };
}
