import { parseRichTextBlocks } from './rich-text-blocks';
import type { Terms } from './terms.model';
const isRec = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
export function parseTerms(body: unknown): Terms | null {
  const data = isRec(body) ? body['data'] : null;
  if (!Array.isArray(data)) throw new Error('terms: unexpected response shape');
  const ok: { at: number; terms: Terms }[] = [];
  for (const raw of data) {
    if (!isRec(raw)) { console.warn('terms: item'); continue; }
    const t = raw['title']; const at = typeof raw['publishedAt'] === 'string' ? Date.parse(raw['publishedAt']) : NaN;
    if (typeof t !== 'string' || t.trim() === '') { console.warn('terms: title'); continue; }
    if (Number.isNaN(at)) { console.warn('terms: publishedAt'); continue; }
    const blocks = parseRichTextBlocks(raw['body']);
    if (!blocks) { console.warn('terms: body'); continue; }
    ok.push({ at, terms: { title: t, blocks } });
  }
  ok.sort((a, b) => b.at - a.at);
  if (ok.length > 1) console.warn('terms: more than one published terms, showing the most recent');
  return ok[0]?.terms ?? null;
}
