import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import type { Country } from '../shared/country.model';
import { CountryContentApi } from './country-content-api';

export type CountryListStatus = 'idle' | 'loading' | 'ready' | 'error';

/**
 * The published countries, loaded once per full page load (ADR-0001). A failed load stays failed
 * until `reload()` (no automatic retries); it never means "country not available".
 */
@Injectable({ providedIn: 'root' })
export class CountryStore {
  private readonly api = inject(CountryContentApi);
  private pending: Promise<void> | null = null;

  readonly status = signal<CountryListStatus>('idle');
  readonly countries = signal<Country[]>([]);

  /** Resolves when the list is loaded or has failed; starts the request only the first time. */
  ensureLoaded(): Promise<void> {
    if (this.pending) return this.pending;
    return this.status() === 'idle' ? this.load() : Promise.resolve();
  }

  /** Asks again after a failure ("Reintentar"). */
  reload(): Promise<void> {
    return this.pending ?? this.load();
  }

  /** The country whose code matches `code`, ignoring case. */
  find(code: string): Country | undefined {
    const wanted = code.toLowerCase();
    return this.countries().find((c) => c.code.toLowerCase() === wanted);
  }

  private load(): Promise<void> {
    this.status.set('loading');
    const request = firstValueFrom(this.api.list()).then(
      (countries) => {
        this.countries.set(countries);
        this.status.set('ready');
      },
      () => {
        this.status.set('error');
      },
    );
    this.pending = request.finally(() => {
      this.pending = null;
    });
    return this.pending;
  }
}
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import type { FieldConfig } from '../shared/field-config.model';
import { FormFieldApi } from './form-field-api';

/**
 * Field configuration per country, kept in memory for this page load only (US-01-Q-16): going
 * back to step 1 does not ask again. A failed or empty answer is never kept, so "Reintentar"
 * always asks again. Rejects when the request fails or times out.
 */
@Injectable({ providedIn: 'root' })
export class FormFieldStore {
  private readonly api = inject(FormFieldApi);
  private readonly cache = new Map<string, FieldConfig[]>();
  private readonly inFlight = new Map<string, Promise<FieldConfig[]>>();

  load(countryCode: string): Promise<FieldConfig[]> {
    const cached = this.cache.get(countryCode);
    if (cached) return Promise.resolve(cached);
    const running = this.inFlight.get(countryCode);
    if (running) return running;
    const request = firstValueFrom(this.api.list(countryCode))
      .then((configs) => {
        if (configs.length > 0) this.cache.set(countryCode, configs);
        return configs;
      })
      .finally(() => this.inFlight.delete(countryCode));
    this.inFlight.set(countryCode, request);
    return request;
  }
}
import { inject } from '@angular/core';
import { CanActivateFn, GuardResult, RedirectCommand, Router } from '@angular/router';
import { CountryStore } from './country-store';
import { PlanStore } from './plan-store';
import { QuoteStore } from './quote-store';
import { wizardStepGuard } from './wizard-step-guard';

/**
 * Step 3 (`/:country/resumen`) opens only with a valid step 1 (otherwise `/<country>/datos`) and
 * a chosen plan that this page load's response still offers (otherwise `/<country>/planes`).
 * A failed plans request also leads to `/planes`, where the error state offers "Reintentar".
 * Redirects replace the blocked address in the history (ADR-0001 note, US-02-AC-15).
 */
export const summaryStepGuard: CanActivateFn = async (route, state) => {
  const router = inject(Router);
  const countries = inject(CountryStore);
  const plans = inject(PlanStore);
  const quote = inject(QuoteStore);

  const step1 = await (wizardStepGuard(route, state) as Promise<GuardResult>);
  if (step1 !== true) return step1;

  const param = (route.paramMap.get('country') ?? route.parent?.paramMap.get('country') ?? '').toLowerCase();
  const toPlans = new RedirectCommand(router.parseUrl(`/${param}/planes`), { replaceUrl: true });
  const chosen = quote.plan();
  const country = countries.find(param);
  if (!chosen || !country) return toPlans;
  try {
    const offered = await plans.load(country.code);
    return offered.some((p) => p.key === chosen.key) ? true : toPlans;
  } catch {
    return toPlans;
  }
};

