import { Component, DestroyRef, ElementRef, afterNextRender, computed, inject, signal, viewChild } from '@angular/core';
import { Title } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { CLOCK } from '../../core/clock';
import { CountryStore } from '../../core/country-store';
import { FormFieldStore } from '../../core/form-field-store';
import { PaymentGateway } from '../../core/payment-gateway';
import { PlanStore } from '../../core/plan-store';
import { QuoteStore } from '../../core/quote-store';
import { RANDOM_DIGITS } from '../../core/random-digits';
import { TermsApi } from '../../core/terms-api';
import type { Country } from '../../shared/country.model';
import { formatMoney } from '../../shared/money-format';
import { calculateFinalPrice } from '../../shared/price-rules';
import { formatQuoteNumber } from '../../shared/quote-number';
import { RichText } from '../../shared/rich-text';
import { buildSummaryRows, type SummaryRow } from '../../shared/summary-rows';
import type { Terms } from '../../shared/terms.model';
import type { Plan } from '../../shared/plan.model';

type Phase = 'idle' | 'processing' | 'rejected' | 'confirmed';
type TermsState = 'loading' | 'error' | 'none' | 'shown';
const APP = 'Cotizador de seguro de auto';

@Component({
  selector: 'app-summary-page',
  imports: [RichText],
  template: `
    <main>
      <div role="status" class="sr">{{ phase() === 'processing' ? 'Procesando pago…' : '' }}</div>
      @if (phase() === 'confirmed') {
        <h1 #heading tabindex="-1">Pago confirmado</h1>
        <p>Tu número de cotización es</p>
        <p>{{ quoteNumber() }}</p>
        <p>Este es un pago simulado; no se realizó ningún cobro real.</p>
        <button type="button" (click)="again()">Nueva cotización</button>
      } @else {
        <div [attr.aria-busy]="phase() === 'processing' ? 'true' : null">
          <h1 #heading tabindex="-1">Resumen de tu cotización</h1>
          <button type="button" [attr.aria-disabled]="busy() ? 'true' : null" (click)="edit()">Editar mis datos</button>
          <button type="button" [attr.aria-disabled]="busy() ? 'true' : null" (click)="changePlan()">Cambiar plan</button>
          @if (ready()) {
            <section><h2>Tus datos</h2>@if (holder().length) { <dl>@for (r of holder(); track r.key) { <dt>{{ r.label }}</dt><dd>@if (r.accessibleValue) { <span aria-hidden="true">{{ r.value }}</span><span class="sr">{{ r.accessibleValue }}</span> } @else { {{ r.value }} }</dd> }</dl> }</section>
            <section><h2>Tu vehículo</h2>@if (vehicle().length) { <dl>@for (r of vehicle(); track r.key) { <dt>{{ r.label }}</dt><dd>{{ r.value }}</dd> }</dl> }</section>
            <section><h2>Plan elegido</h2><p>{{ plan()?.name }}</p><p>{{ plan()?.shortDescription }}</p><p>{{ price() }} <span>Precio anual</span></p></section>
          }
          <section [attr.aria-busy]="termsState() === 'loading' ? 'true' : null">
            <h2>Términos y condiciones</h2>
            @switch (termsState()) {
              @case ('loading') { <p role="status">Cargando términos y condiciones…</p> }
              @case ('error') { <p role="alert">No pudimos cargar los términos y condiciones. Intenta de nuevo.</p><button type="button" (click)="loadTerms()">Reintentar</button> }
              @case ('none') { <p role="status">Los términos y condiciones no están disponibles en este momento. No es posible pagar.</p> }
              @case ('shown') {
                <div role="region" tabindex="0" aria-labelledby="terms-title">
                  <h3 id="terms-title">{{ terms()?.title }}</h3>
                  <app-rich-text [blocks]="terms()!.blocks" [headingLevel]="4" />
                </div>
                <label><input type="checkbox" [checked]="accepted()" [disabled]="busy()" (change)="toggle($event)" /> Acepto los términos y condiciones</label>
              }
            }
          </section>
          <fieldset [disabled]="busy()">
            <legend>Simulación de pago (no se realiza ningún cobro)</legend>
            <label><input type="radio" name="outcome" value="approved" [checked]="outcome() === 'approved'" (change)="outcome.set('approved')" /> Pago aprobado</label>
            <label><input type="radio" name="outcome" value="rejected" [checked]="outcome() === 'rejected'" (change)="outcome.set('rejected')" /> Pago rechazado</label>
          </fieldset>
        </div>
        @if (hint()) { <p id="pay-hint">Acepta los términos y condiciones para pagar.</p> }
        <button type="button" [attr.aria-disabled]="canPay() ? null : 'true'" [attr.aria-describedby]="hint() ? 'pay-hint' : null" (click)="payNow()">{{ phase() === 'processing' ? 'Procesando pago…' : 'Pagar' }}</button>
        @if (phase() === 'rejected') { <p role="alert">El pago fue rechazado y no se realizó ningún cobro. Puedes intentarlo de nuevo.</p> }
      }
    </main>
  `,
})
export class SummaryPage {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly countries = inject(CountryStore);
  private readonly fields = inject(FormFieldStore);
  private readonly plans = inject(PlanStore);
  private readonly quote = inject(QuoteStore);
  private readonly termsApi = inject(TermsApi);
  private readonly gateway = inject(PaymentGateway);
  private readonly clock = inject(CLOCK);
  private readonly random = inject(RANDOM_DIGITS);
  private readonly title = inject(Title);
  private readonly heading = viewChild<ElementRef<HTMLHeadingElement>>('heading');
  private readonly abort = new AbortController();
  private destroyed = false;

  protected readonly ready = signal(false);
  protected readonly holder = signal<SummaryRow[]>([]);
  protected readonly vehicle = signal<SummaryRow[]>([]);
  protected readonly plan = signal<Plan | null>(null);
  protected readonly price = signal('');
  protected readonly terms = signal<Terms | null>(null);
  protected readonly termsState = signal<TermsState>('loading');
  protected readonly accepted = signal(false);
  protected readonly outcome = signal<'approved' | 'rejected'>('approved');
  protected readonly phase = signal<Phase>('idle');
  protected readonly quoteNumber = signal('');
  protected readonly busy = computed(() => this.phase() === 'processing');
  protected readonly canPay = computed(() => this.termsState() === 'shown' && this.accepted() && this.phase() !== 'processing' && this.phase() !== 'confirmed');
  protected readonly hint = computed(() => this.termsState() === 'shown' && !this.accepted());
  private country: Country | undefined = this.countries.find(this.route.snapshot.paramMap.get('country') ?? '');

  constructor() {
    inject(DestroyRef).onDestroy(() => { this.destroyed = true; this.abort.abort(); });
    this.title.setTitle(`Resumen de tu cotización | ${APP}`);
    void this.load();
    void this.loadTerms();
    afterNextRender(() => this.heading()?.nativeElement.focus());
  }

  private async load(): Promise<void> {
    const country = this.country!;
    const [offered, configs] = await Promise.all([this.plans.load(country.code), this.fields.load(country.code)]);
    const step1 = this.quote.completeStep1(configs)!;
    const chosen = offered.find((p) => p.key === this.quote.plan()?.key)!;
    const rows = buildSummaryRows(configs, step1, country.locale);
