  }
  async function bodyOf(response: APIResponse): Promise<TermsBody> {
    // The proxy answers an unknown (upper-case) path with the SPA's HTML page: no rows, no draft.
    try {
      return (await response.json()) as TermsBody;
    } catch {
      return {};
    }
