    await expect(field(page, 'Placa')).toBeVisible();
    await reachSummaryInColombia(page);
    await expect(page.getByRole('region', { name: CO_TERMS_TITLE })).toBeVisible();
    await expect(page.getByText(NEW_TITLE)).toHaveCount(0);
    await expect(page.getByText(NEW_TEXT)).toHaveCount(0);

    // The browser never held a Strapi credential: only the front end origin was spoken to with no Authorization header.
    const leaked = await page.evaluate(() => JSON.stringify({ local: { ...localStorage }, session: { ...sessionStorage }, cookie: document.cookie }));
    expect(leaked).not.toContain(token.accessKey);
    expect(leaked).not.toContain(session.jwt);
  });

  test('US-03-AC-14 after the teardown the terms are gone again on the next reload (the seed terms are back)', async ({ page }) => {
    // Runs after the teardown of the test above only when that one deleted its terms; here the check is on the content API.
    const found = await api.get('/api/terms', { params: { 'filters[title][$eq]': NEW_TITLE } });
